// adapted from:  https://www.shadertoy.com/view/wstyRB
//  Casts ray in rd direction from ro, estimates depth and normal 
float iSupportFunction( in vec3 ro, in vec3 rd, obj o, out vec3 normal, int ITERATIONS)
{   


    vec3 dir, tmp;   
    vec3 a,b,c,d;
    ro-=o.c;
     float d0=- dot(ro,rd);  
    //RX=horizontal axis, RY=vertical axis
    rd=normalize(rd);
    vec3 rx =normalize(cross(rd,VAXIS)),ry=cross(rx,rd);
    //switch to local coordinates
    normal=VAXIS;

    //rd*=-1.;
   mat3 rmai=mat3(rx,ry,rd),rma=transpose(rmai);

    ro*=rmai;

    mat3 rm= rma *
    mat3(
        rotate(o.r,vec3(1,0,0)),
        rotate(o.r,vec3(0,1,0)),
        rotate(o.r,vec3(0,0,-1))
    );  
    o.c =  cross(cross(vec3(0,0,1),ro),vec3(0,0,1)); 
    //o.r=o2.r;

    #define perp2d(v)  ((v).yx*vec2(-1,1))  //(cross(v,vec3(0,0,-1)).xy) 
    a=o.c;

    dir=vec3(-a.xy, 0.);
    for(int st=ZERO;st<4;st++){  
      int N=0; if(st>1) N=ITERATIONS;
      for (int i = ZERO;i <=N; i++){

        //supporto fonction of rotated & translated object
        d=dir*rm;
        d= support(d,  o)*transpose(rm)+o.c;       

        if(st==0){              
                b=d;
                if (dot(-a.xy, b.xy) <= 0.) return NOHIT;
                dir = vec3(perp2d(b-a),0.);
                if (dot(dir.xy, a.xy) >= 0.) {  dir.xy *= -1.; tmp = a; a = b; b = tmp;}            
        }
        else if(st==1){             
                c=d;
                if (dot(c.xy, dir.xy) <= 0.) return (NOHIT);             
        }
        else if(st==2){            
                c=d;
                if (dot(c.xy, dir.xy) <= 0.) return (NOHIT);                    
                if (i == 3) return (NOHIT);
                if (dot(dir.xy = perp2d(c-a), c.xy) < 0.) {b = c;}
                else if (dot(dir.xy = perp2d(b-c), c.xy) < 0.)   {a = c;}
                else break; // Origin in triangle -> intersection!    

        }
        else if(st==3){               
                if (abs(dot(dir, d) - dot(dir, a)) < TOLERANCE) break;

                // xd = origin left of xd line
                bool ad = dot(perp2d(d-a), d.xy) > 0.;
                bool bd = dot(perp2d(d-b), d.xy) > 0.;
                bool cd = dot(perp2d(d-c), d.xy) > 0.;

                // Choose triangle that intersects z-axis furthest in z direction
                if (ad && !bd) {c = d;}
                else if (bd && !cd) {a = d;}
                else if (cd && !ad) {b = d;}
                //else break; // continuing is better on spheres 

                dir = normalize(cross(b-a, c-a));  
        }
      }
    }
    normal = -normalize(cross(b-a, c-a));
    float depth = a.z + dot(a.xy, normal.xy)/normal.z ;   
    normal=normal*rma;
    return  (  -depth +d0);   

}



float minDist;
vec3 minDistNormal;
vec3 minDistCol;
int minCi=-1;


void renderObj(int ci, vec3 rayPos,vec3 rayDir,bool shadow){


     obj oo = obj(getCubePos(ci).xyz,getCubeShape(ci),getCubeQuat(ci));    
     if ( length(cross(oo.c-rayPos,rayDir))>length(oo.b)) return;

     if(oo.b.w==0.   && material(ci)>0. && keyToggle(70) &&shadow) return;
     vec3 oNor;
     float t= iSupportFunction( rayPos, rayDir, oo,oNor,shadow? 5: 20);
     if( minDist>t && t>0. ){
         vec3 lp=rotateInv(oo.r,rayPos+t*rayDir-oo.c);           
         vec3 ap=abs(lp/oo.b.xyz);
         float br =length(ap*.5*(step(ap,ap.zxy)*step(ap.yzx,ap)+ step(ap,ap.yzx)*step(ap.zxy,ap)));
         float ct =length(step(vec3(0.),-4.9+(mod(lp,5.))));
         vec4 pr=getPressure(iChannel3,ci);

#ifdef WIREFRAME         
         if(oo.b.w==0.   && material(ci)>0. && keyToggle(70) && br<.45) {
             float t2 = -iSupportFunction( rayPos, -rayDir, oo,oNor);
              lp=rotateInv(oo.r,rayPos+t2*rayDir-oo.c);           
              ap =abs(lp/oo.b.xyz);
              br =length(ap*.5*(step(ap,ap.zxy)*step(ap.yzx,ap)+ step(ap,ap.yzx)*step(ap.zxy,ap)));
              if(br<.45){minDistCol-=vec3(.1); return;}
              oNor*=-1.;

         }
#endif

         minDist=t-.0001;
         minDistNormal= oNor;
         minCi=ci;

         minDistCol=  
              material(ci)<1.? vec3(.3): cos(oo.b.w*6.28/float(SHAPES)+vec3(0,2,4))*.1+.6;

        if((oo.b.w!=0. || material(ci)<1.) && ct>=1.) minDistCol*=2.;
        if(oo.b.w==0.  && br>=.45) minDistCol/=2.;



       if(!keyToggle(72)) {

           minDistCol.xyz=minDistCol.xyz*.1+.4+pr.w*vec3(3,1,0);
       }


       if(ci== gVars.z &&ci>0) minDistCol=vec3(0,0,1);
       int select=int(getCubePos(ci).w);
       if(select>0) minDistCol=vec3(select&2,select&1,0);
     }

}


vec3 backGround(vec3 dir,vec3 pos)
{
	vec3 color = skyColor*(dot(dir,sunDir)*-0.3+1.0);
	if (dot(sunDir,dir)>0.0) 
	{
	 float f = max(length(cross(sunDir,dir))*10.0,1.0);		
	 color += sunColor*40.0/(f*f*f*f);
	}
	return color;
}

vec3 getRayDir(vec3 ro, vec3 lookAt, vec2 uv) {
	vec3 f = normalize(lookAt),
		 r = normalize(cross(VAXIS, f));
	return normalize(f + r * uv.x + cross(f, r) * uv.y);
}

