vec4 pInt(vec2 p, int nc,float n,int cc) {
    vec4 v = vec4(0);
    int nnc=int(log(n)/log(9.99999));
    if (nnc<nc)  {p-=vec2(nc-nnc,0)*.5; nc=nnc;}
    for (float i = float(nc); i>=0.; i--)  n /=  9.999999, v += char(p - .5*vec2(i,0), 48+ int(fract(n)*10.),cc );
    return v;
}
