vec3 supMax(vec3 d, vec3 a, vec3 b) { return dot(d,a) > dot(d,b) ? a : b;}

//base support fuctions
vec3 support(vec3 dir, obj o){
    const float h=(sqrt(5.)-1.)*.5,h2=h*h;
    if(o.b.w==1.) //ELLIPSE
        return normalize(dir*o.b.xyz)*(o.b.xyz) + sign(dir)*(o.b.xyz)*.0001;
    else if(o.b.w==2.) //CYLINDER
        return  supMax( dir, vec3(normalize(dir.xy*o.b.xy)*o.b.xy, o.b.z),vec3(normalize(dir.xy*o.b.xy)*o.b.xy, -o.b.z) );


    else if(o.b.w==3.) //CONE
        return  
             supMax( dir,
            vec3(normalize(dir.xy*o.b.xy)*o.b.xy, .5*o.b.z) ,
            vec3(0.,0,-o.b.z));
#if SHAPES > 4  
    else if(o.b.w==4.) //DOUBLE CONE
        return  supMax(dir,
           vec3(0,0,-o.b.z),
             supMax( dir,
            vec3(normalize(dir.xy*o.b.xy)*o.b.xy, 0.) ,
            vec3(0,0,o.b.z)));           
    else if(o.b.w==5.) return //OCTAHEDRON
       supMax(dir, vec3(0,0,sign(dir.z)*o.b.z),
       supMax(dir,vec3(sign(dir.x)*o.b.x,0,0),
                  vec3(0,sign(dir.y)*o.b.y,0))

        ); 
   else if(o.b.w==6.) { //WHATEVERHEDRON
           #define ROT2(ANG) mat2(cos(ANG),sin(ANG),-sin(ANG),cos(ANG))
         vec3 s=vec3(1,0,0)*o.b.x;
         float TAU=6.28;
         for ( float cc = 0.; cc < TAU; cc += TAU/3.1 )
          for ( float bb = 0.; bb < TAU; bb += TAU/3.6 )
          for ( float aa = 0.; aa < TAU; aa += TAU/3.1 )
          {
            vec3 n = vec3(1,0,0);
            n.xy *= ROT2(aa);
            n.yz *= ROT2(cc);
            n.xz *= ROT2(bb);
            s=supMax(dir,s,n*o.b.xyz);
         }
         return s;
         } 
#endif
    else if(o.b.w==7.) { //FACE-CAPSULE
        return sign(dir)*vec3(abs(o.b.xy -o.b.zz),0.0001) + normalize(dir)*(o.b.z);
    }

   else return sign(dir)*o.b.xyz; // BOX (DEFAULT)
} 


