vec3 rotate(vec4 quat,vec3 v)
{
    float sinsqr = (1.0-quat.w*quat.w);
    if (sinsqr!=0.0)
    {
        v=v*quat.w + quat.xyz*((dot(v,quat.xyz)*(1.0-quat.w))*(1.0/sinsqr)) + cross(v,quat.xyz);
        v=v*quat.w + quat.xyz*((dot(v,quat.xyz)*(1.0-quat.w))*(1.0/sinsqr)) + cross(v,quat.xyz);
    }
    return v;
}

vec3 rotateInv(vec4 quat,vec3 v)
{
    quat.xyz*=-1.;
    return rotate( quat, v);
}


mat3 getMatrix(vec4 quat) {
    float qx = quat.x,qy = quat.y, qz = quat.z, qw = quat.w;
    float qx2 = qx * qx, qy2 = qy * qy, qz2 = qz * qz;

 	return mat3(
        1.0 - 2.0*qy2 - 2.0*qz2,	2.0*qx*qy - 2.0*qz*qw,	2.0*qx*qz + 2.0*qy*qw, 
    	2.0*qx*qy + 2.0*qz*qw,	1.0 - 2.0*qx2 - 2.0*qz2,	2.0*qy*qz - 2.0*qx*qw, 
    	2.0*qx*qz - 2.0*qy*qw,	2.0*qy*qz + 2.0*qx*qw,	1.0 - 2.0*qx2 - 2.0*qy2
    );
}
vec4 getRotation(vec3 x,vec3 y,vec3 z){
    // convert back to quaternion
	float trace = x.x + y.y + z.z;
    vec4 q;
	if( trace > 0.0 ) {
		float s = 0.5 / sqrt(trace+ 1.0);
		q=vec4(( z.y - y.z ) * s,( x.z - z.x ) * s,( y.x - x.y )*s, 0.25 / s);		
	} else {
		if ( x.x > y.y && x.x > z.z ) {
		    float s = 2.0 * sqrt( 1.0 + x.x - y.y - z.z);
			q =vec4( 0.25 * s,(x.y + y.x ) / s,(x.z + z.x ) / s,(z.y - y.z ) / s);
		} else if (y.y > z.z) {
			float s = 2.0 * sqrt( 1.0 + y.y - x.x - z.z);
			q = vec4((x.y + y.x ) / s,0.25 * s, (y.z + z.y ) / s,(x.z - z.x ) / s);
		} else {
			float s = 2.0 * sqrt( 1.0 + z.z - x.x - y.y ); 
			q= vec4((x.z + z.x ) / s,(y.z + z.y ) / s,0.25 * s,(y.x - x.y ) / s);
		}
	}   
    return normalize(q); 
}

vec3 rotateAxis(vec3 axis,vec3 v)
{
    float angle = length(axis);
    if (angle==0.0) return v; 
    else {
        axis/=angle;

        return v*( cos(angle) +  axis* axis * (1.0-cos(angle)))  + cross(v,axis)*sin(angle);

    }
}

