vec3 hash32(vec2 p)
{
	vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yxz+33.33);
    return fract((p3.xxy+p3.yzz)*p3.zyx);
}

void copy(inout vec3[3] c, inout vec3[3] d){c[0]=d[0];c[1]=d[1];c[2]=d[2];}
void swap(inout vec3[3] b, inout vec3[3] c) {vec3 t =b[0]; b[0]=c[0];c[0]=t; t =b[1]; b[1]=c[1];c[1]=t; t =b[2];b[2]=c[2];c[2]=t;}

int MPRPenetration(inout obj o1, inout obj o2 , out float depth, out vec3 dir, out vec3 pos)
{


    vec3[3] a,b,c,d,s;

    int st=0; //phase
    for(st=ZERO;st<=3;st++){

        vec3[3] v;
        int iter=ZERO;
        bool inside=false; //if true, origin is inside
        while(iter<ZERO+(st<=1?1:10)){

            //BEGIN PRE
            if(st==0){
                dir= vec3(0,1,0);   
                a[1]=o1.c;a[2]=-o2.c; a[0]= a[1]+a[2]; 

                if (a[0]==vec3(0)) {a[1]+= vec3(1e-3,0,0); a[0]+=vec3(1e-3,0,0);}

                dir= -normalize(a[0]); 
            }
            if(st==1){
                copy(b,s);
                if ( dot(b[0], dir) <=0.) return -1;

                dir = cross(a[0], b[0]);					 					   
                if (length(dir)==0.){
                    if (b[0] == (o1.c-o2.c)) {

                        depth = 0.;
                        dir= vec3(0,1,0); 
                        pos=(b[1]+b[2])*.5;
                        return 1;
                    }
                    else {
                         pos=(b[1]+b[2])*.5;
                         depth = length(b[0]);
                         dir =normalize(b[0]);
                         return 2;
                    }
                }
            }
            if(st==3){
                dir= normalize(cross( c[0]-b[0], d[0]-b[0]));

                if ( dot(dir, b[0])>= 0.) inside=true;
            }
            //END PRE

            //Minkowsky difference support function
            s[1] = support(rotateInv(o1.r,dir),o1);   
            s[1]=  rotate(o1.r, s[1] +rotateInv(o1.r,o1.c)); 

            s[2] = support(rotateInv(o2.r,-dir),o2);
            s[2]=  -rotate(o2.r,s[2] +rotateInv(o2.r,o2.c));

            s[0] = s[1]+s[2];

            //BEGIN POST
            if(st==1){    
                copy(c,s);             
                if ( dot(c[0], dir) <=0.) return -1;  

                dir= normalize(cross(b[0]-a[0],c[0]-a[0]));
                if (dot(dir, a[0]) > 0.){
                    swap(b,c);
                    dir *=-1.;
                }
            }
            if(st==2){    
                copy(d,s);
                if (dot(d[0], dir) <=0.) return -2;

                if ( dot(cross (b[0],d[0]), a[0])  < 0. ) copy(c,d);
                else if (dot(cross (d[0],c[0]), a[0]) < 0. ) copy(b,d);
                else break; //next phase

                dir =normalize(cross( b[0]-a[0], c[0]-a[0]));

            }
            if(st==3){    
                copy(v,s);

                float dv4 = dot(v[0], dir);
                if (dv4 <0. && ! inside ) return  -3;

                float dv1 = dot(b[0], dir);
                float dv2 = dot(c[0], dir);
                float dv3 = dot(d[0], dir);        
                bool portalReachTolerance=   (min(min(dv4 - dv1, dv4 - dv2),dv4 - dv3)  <= 1e-6);

                if(portalReachTolerance && inside) break;

                vec3 vn =cross( v[0],a[0]);   
                if (dot(b[0], vn) > 0.) { if(dot (c[0], vn) > 0.) copy(b,v); else  copy(d,v);}
                else{  if(dot(d[0], vn) > 0.)  copy(c,v); else copy(b,v);  }        

            }            
            //END POST

            iter++;
            continue;
        }
    }   


    //  Penetration info
    //---------------------------------
    // Iq :  https://www.shadertoy.com/view/ttfGWl
    vec3 v10 = c[0] - b[0]; 
    vec3 v21 = d[0] - c[0]; 
    vec3 v02 = b[0] - d[0]; 
    vec3 nor = cross( v10, v02 );

    if( dot(cross(v10,nor),b[0])>0.0 )      dir=  b[0] + v10*clamp( -dot(b[0],v10)/dot(v10,v10), 0.0, 1.0 );
    else if( dot(cross(v21,nor),c[0])>0.0 ) dir=  c[0] + v21*clamp( -dot(c[0],v21)/dot(v21,v21), 0.0, 1.0 );
    else if( dot(cross(v02,nor),d[0])>0.0 ) dir=  d[0] + v02*clamp( -dot(d[0],v02)/dot(v02,v02), 0.0, 1.0 );
    else dir=   nor*dot(nor,b[0])/dot(nor,nor);
    depth=  sqrt(dot(dir,dir));  
    dir  = normalize(dir);             
    if (depth<=-1e-3) dir=vec3(0,1,0);

    // barycentric coordinates:
    float k0,k1,k2,k3, sum;

    // use barycentric coordinates of tetrahedron to find origin    
    k0 = dot(cross(b[0],c[0]),d[0]);
    k1 = dot(cross(d[0],c[0]),a[0]);
    k2 = dot(cross(a[0],b[0]),d[0]); 
    k3 = dot(cross(c[0],b[0]),a[0]);  

    sum = k0 + k1 + k2 + k3;
//   if (sum<=0.){              
//       k0 = 0.;
//       k1 = dot(cross(b[0],c[0]),dir);  
//       k2 = dot(cross(d[0],b[0]),dir);  
//       k3 = dot(cross(b[0],c[0]),dir);   
//       sum = k1 + k2 + k3;
//   }

    vec3 p1= a[1]*k0+b[1]*k1+c[1]*k2+d[1]*k3;
    vec3 p2= a[2]*k0+b[2]*k1+c[2]*k2+d[2]*k3;

    pos=.5*(p1-p2)/sum;

    return 0;
}

bool getCollision(obj o1, obj o2, out float idepth,out vec3 idir, out vec3 ipos){

    bool intersect =false;



    if(length(o1.c-o2.c)>length(o1.b)+length(o2.b)) intersect=false;
    else intersect =  MPRPenetration( o1 ,  o2 , idepth,  idir,   ipos )>=0;

    intersect=intersect 
        && !isnan(length(ipos)) 
        && !isnan(idepth)
        && !isnan(length(idir));

    return intersect;
}




void initBlock(int cubei, 
    out vec4 pos,
    out vec4 quat,
    out vec3 vel,
    out vec3 rotvel,
    out vec4 shape,
    out vec4 pressure
)
{
        vel =    vec3(0);
        rotvel = vec3(0);
        quat =   vec4(0.0,0.0,0.0,1.0);
        shape=   vec4(
            cubei==0?vec3(50,1,50):cubei<STATIC_OBJ_COUNT?vec3(20,6,.5) : OBJSIZE,
            cubei<STATIC_OBJ_COUNT?0:cubei%SHAPES
        );
        if(cubei>=STATIC_OBJ_COUNT && (cubei&1)>0) shape.xyz=(cubei&3)==0?shape.yyy: shape.xxx;


        pressure=vec4(0);

        if (cubei<STATIC_OBJ_COUNT) // static floor
        {
            pos = vec4(0,-1,0,0);

            if(cubei==0){
                vec3 ro = vec3(SLOPE,0,0.);
                quat = rotateRotation(normalize(vec4(0.0,0.0,0.0,1.0)),ro);

            }
            if(cubei>0){
                vec3 ro = vec3(0.,PI*(float(cubei)*2.0)/4.,0.);
                pos.xyz = rotateAxis(ro,   vec3(0,0,20));
                quat = rotateRotation(normalize(vec4(0.0,0.0,0.0,1.0)),ro);
            }
            return;
        }

    	cubei-=STATIC_OBJ_COUNT; 

#ifdef STACK 
        pos.xyz = vec3(-STACK.x,1.01,-STACK.z)*.75*OBJSIZE + vec3((cubei/STACK.z)%STACK.x,cubei/(STACK.z*STACK.x),cubei%STACK.z)*OBJSIZE*2.01 ;
#else
        if(cubei<100){
            float n=20.;
            shape=vec4(vec3(.8,1,.6),0);
            vec2 lv=vec2(cubei%int(n), cubei/int(n));
            float a= 6.283/n*(lv.x +lv.y*.5);
            pos.xyz= vec3(0,.5+lv.y,0)*shape.y*2.01+
                +vec3(cos(a),0,sin(a))*shape.x*n/3.141*1.2;


             vec3 rd=normalize(vec3(pos.x,0,pos.z)),rx =normalize(cross(rd,VAXIS)),ry=cross(rx,rd);
             quat = getRotation( rx,ry,-rd );   
         }
        else{
            shape=vec4(vec3(.4),1);
            vec3 lv=hash32(vec2(cubei,gFrame));
            float a= 6.28*lv.x;
            pos.xyz= vec3(cos(a),lv.y*.1,sin(a))*50.;
             vel= -normalize(pos.xyz-vec3(0,36,0))*.4 +lv.z*.05-.025;
            // mass*=.1;             
        }
#endif        
}


void simulate( sampler2D ch, sampler2D chKey, int bufId, out vec4 fragColor, in ivec2 fragCoord )
{

    gVars=ivec4(getGlobal(ch,0));
    gVars.x=max(0,min(gVars.x,int(gRes.x)-1)); 
    fragColor = vec4(0);

    int ci = (fragCoord.x)-1;
    if (fragCoord.y>=7) discard;


    if(ci<0) {//GLOBALS
        vec4 prev = getGlobal(ch,fragCoord.y);
        fragColor=prev;
        int mode=  gVars.y; // 1=camera,0=demo
        if(fragCoord.y==0)  {
            //x=COUNT,Y=MODE,Z=selected,W=first multiple
            fragColor.x= (INIT)?float(OBJ_COUNT_INIT):
            float( gVars.x + ((keyPressed(71)|| DEMO) && bufId==3?1:0));
            fragColor.y= (INIT)?0.:float((mode + (keyDown(77)&& bufId==3?1:0))%2);
            fragColor.z= (INIT) || keyDown(76)?float(0):mod(prev.z+(keyDown(75)&&bufId==3?1.:0.)-(keyDown(74)&&bufId==3?1.:0.),prev.x);

        fragColor.w=0.;
            for( int cj= int(gVars.x); cj>STATIC_OBJ_COUNT;cj--){
               if( getCubePos(ch,cj).w>1.)fragColor.w=float(cj);
            }
        }
        if(fragCoord.y==1) { //CAMERA 
            if(INIT ) fragColor.xyz=vec3(10,17.,10);
            if((INIT && gFrame>0)||  ( mode!=1 &&gMouse.z>0. ) ){

                float a  = gMouse.x/gRes.x*6.28-3.14, d=25.* gMouse.y/gRes.y; 
                if(gVars.w<1)
               fragColor.xz = vec2(-d*sin(a),-d*cos(a))+(gVars.z>0? getCubePos(ch,gVars.z).xz:vec2(0));
            } 
            if(keyPressed(83) &&gVars.y==1) fragColor.xyz-=getGlobal(ch,2).xyz*.03;
            if(keyPressed(87) &&gVars.y==1) fragColor.xyz+=getGlobal(ch,2).xyz*.03;
            if(keyPressed(81) &&gVars.y==1 ) fragColor.y-=.03;
            if(keyPressed(69) &&gVars.y==1) fragColor.y+=.03;
            if(keyPressed(65) &&gVars.y==1) fragColor.xyz+=cross(getGlobal(ch,2).xyz,VAXIS)*.03;
            if(keyPressed(68) &&gVars.y==1) fragColor.xyz-=cross(getGlobal(ch,2).xyz,VAXIS)*.03;
        }
        if(fragCoord.y==2) {//LOOKAT

            if(INIT || mode!=1 ) fragColor.xyz=-normalize(getGlobal(ch,1).xyz-(gVars.z>0? getCubePos(ch,gVars.z).xyz:vec3(0)));
            if((INIT &&gFrame>0) || mode==1 &&gMouse.z>0. ){                
               float a = gMouse.x/gRes.x*6.284-3.1416, b=gMouse.y/gRes.y*3.141-1.5708;           
                fragColor.xyz=vec3(cos(b)*sin(a),sin(b),cos(b)*cos(a));
            }                           
        }
        return;
    }



    if (ci>=  gVars.x+1) discard;

    vec4 pos =  getCubePos(ch,ci);
    vec4 quat  = getCubeQuat(ch,ci);
    vec3 vel = getCubeVel(ch,ci),v0 =vel;
    vec3 rotvel = getCubeRotVel(ch,ci),rv0=rotvel;
    vec4 shape =getCubeShape(ch,ci);
    vec4 mass=vec4(1e9); 

    mass.x=ci<STATIC_OBJ_COUNT?  1e9: shape.x*shape.y*shape.z*8.;
           mass.yzw=vec3(mass.x/3./shape.x/shape.y/shape.z)*vec3(
           shape.y*shape.y+shape.z*shape.z,
           shape.x*shape.x+shape.z*shape.z,
           shape.x*shape.x+shape.y*shape.y);
    vec4 imi=1./mass;

    vec4 pressure = getPressure(ch,ci)*PRESSURE;

    pos.w=keyPressed(76)?0.: floor(pos.w/2.)*2.; //=selected*2 + mouseover

    obj o1,o2;
    float depth;
    vec3 collNormal,collpos;

    o1 = obj(getCubePos(ch,ci).xyz,getCubeShape(ch,ci),getCubeQuat(ch,ci)); 

    if(INIT &&ci>=0 && ci<= gVars.x) initBlock(ci,pos,quat,vel, rotvel, shape,pressure);
    else if((keyPressed(71)|| DEMO) && ci>= gVars.x &&bufId==3){
         initBlock(ci,pos,quat,vel, rotvel, shape,pressure);
     // if(gVars.z>=STATIC_OBJ_COUNT && gVars.z<gVars.x){
     //     pos =  getCubePos(ch,gVars.z);
     //     quat  = getCubeQuat(ch,gVars.z);
     //     shape =getCubeShape(ch,gVars.z);
     //     pos.y+=shape.y*4.;
     //     vel=vec3(0);rotvel=vec3(0);
     //      mass = getMass(ch,gVars.z),imi=1./mass;    
     //      pressure = vec4(0);
     // }
    }
    else if (ci>=STATIC_OBJ_COUNT && !keyToggle(66))
    {  



        float dt=min(dt_max,30./gFrameRate);


        mat3 imim=mat3(imi.y,0,0,0,imi.z,0,0,0,imi.w);
        mat3 rm= mat3(rotate(o1.r,vec3(1,0,0)), rotate(o1.r,vec3(0,1,0)),rotate(o1.r,vec3(0,0,-1)) );  
        imim=rm*imim*transpose(rm);

        //vec3 rep=pressure.xyz;//vec3(0);
        for(int cj=ZERO-1;cj<gVars.x;cj++)
        {            

            if(cj==ci) continue;

            //MOUSE RAY OBJECT if cj==-1
             if( gMouse.z>0.&&cj==-1){
                vec2 uv= (gMouse.xy-gRes.xy*.5)/gRes.y;
                vec3 rd=getGlobal(ch,2).xyz;    
                rd= normalize(rd - normalize(cross(rd,VAXIS)) * uv.x - cross(rd, normalize(cross(rd,VAXIS))) * uv.y);  
                vec4 q =getRotation( rd,normalize(cross(rd,VAXIS)),cross(rd, normalize(cross(rd,VAXIS))) );        
                o2 = obj(getGlobal(ch,1).xyz ,vec4(50.,.0,0.0,7),q);
            }else                       
            o2 = obj(getCubePos(ch,cj).xyz,getCubeShape(ch,cj),getCubeQuat(ch,cj));    

            vec4 imj = 1./getMass(ch,cj);


            bool coll=getCollision( o2,  o1,  depth, collNormal, collpos);

            if (coll)
            {

                if(cj<0 && ci>=STATIC_OBJ_COUNT){
                    float newState=keyPressed(79)?3.: keyPressed(80)?1.: 1.+pos.w;
                    pos.w =newState;
                    continue;
                }

                vec3 vci = cross(collpos-o1.c,rv0) + v0;
                vec3 vcj = cross(collpos-o2.c,getCubeRotVel(ch,cj)) + getCubeVel(ch,cj);

                mat3 imjm=mat3(imj.y,0,0,0,imj.z,0,0,0,imj.w);
                mat3 rm= mat3(rotate(o2.r,vec3(1,0,0)), rotate(o2.r,vec3(0,1,0)),rotate(o2.r,vec3(0,0,-1)) );  
                imjm=rm*imjm*transpose(rm);

                if (cj<STATIC_OBJ_COUNT) {imjm *= .0;imj*=0.;}
                vec3 veldiff = vcj-vci;

                vec3 impulse = veldiff;
                float perpart = dot(collNormal,impulse);
                vec3 tangentialpart = impulse-collNormal*perpart;
                if (length(tangentialpart)>perpart*FRICTION)
                {
                    tangentialpart *= (perpart*FRICTION)/length(tangentialpart);
                    impulse = tangentialpart + collNormal*perpart;
                }
                if (perpart<0.0) impulse = vec3(0.); 

                //if(impulse!=vec3(0)) collNormal=normalize(impulse);
                impulse*=(ELASTICITY)/(
                    imi.x+imj.x
                    +dot(cross(cross(imim*(collpos-o1.c),collNormal),collpos-o1.c),collNormal)+
                    +dot(cross(cross(imjm*(collpos-o2.c),collNormal),collpos-o2.c),collNormal)
                );


                //repulsion
                pressure.xyz += collNormal*depth*REPULSION;               
                pressure.w+=depth;

                //if(max(o1.b.w,o2.b.w)==0. && length(impulse.xz)/abs(impulse.y)<1e-4) impulse.xz*=0.;
                if(length(veldiff)>.05 || pressure.w<=.2)
                    vel += dt*impulse*imi.x;

                if(o1.b.w!=0. || length(impulse.xz)/abs(impulse.y)>1e-6)
                    rotvel -= dt*cross(collpos-o1.c,impulse)*imim;
            }


            if(keyToggle(84)   && dot(pressure.xyz,o1.c-o2.c)>=-0.05 ) vel+= normalize(o1.c-o2.c)/dot(o1.c-o2.c,o1.c-o2.c)*dt*ATTRACTION/max(imj.x,1.);
        }

        if(pressure.w>.6 && length(vel)<.2) vel/=(pressure.w/.05+1.);
        //if(o1.b.w==0. && length(vel.xz)/abs(vel.y)<.01) vel.xz*=0.;      

        // move by adding velocity to position, and rotate
        pos.xyz += dt*vel;
        pos.xyz += pressure.xyz;
        quat = rotateRotation(quat,rotvel*dt);

        if(pressure.y<.005  && pos.w==0.  && !keyToggle(82)  && ci!=gVars.z) vel.y += dt*GRAVITY;

        vel*=DECAY;
        rotvel*=DECAY;

    }   

    bool actionable= ci>=STATIC_OBJ_COUNT  && (gVars.z==ci || pos.w>1.);

    if(actionable){

        shape.w=float((int(shape.w)+(keyDown(50) ?1:0)-(keyDown(49) ?1:0))%SHAPES);

        if(keyPressed(51)) { shape.x+=.05;}
        if(keyPressed(52)) { shape.x-=.05;}
        if(keyPressed(53)) { shape.y+=.05;}
        if(keyPressed(54)) { shape.y-=.95;}
        if(keyPressed(55)) { shape.z+=.05;}
        if(keyPressed(56)) { shape.z-=.05;}
        if(keyPressed(57)) {vel=vec3(0);rotvel=vec3(0);quat=vec4(0,0,0,1);}
        shape.xyz=clamp(shape.xyz,vec3(.2),vec3(5));
        vec3 rq =.02*vec3(keyPressed(90),keyPressed(88),keyPressed(67));
        quat = rotateRotation(quat,rotate(quat,rq));
    } 
    if(gVars.y!=1 && actionable){//ci==gVars.z && ci>=STATIC_OBJ_COUNT) {
        vec3 rd= getGlobal(ch,2).xyz,rl=normalize(cross(rd,VAXIS));rd=cross(rl,VAXIS);
        if(keyPressed(81) ) pos.y-=.03;
        if(keyPressed(69) ) pos.y+=.03;
        if(keyPressed(65) ) pos.xyz+=rl*.03;
        if(keyPressed(68) ) pos.xyz-=rl*.03;
        if(keyPressed(83) ) pos.xyz+=rd*.03;
        if(keyPressed(87) ) pos.xyz-=rd*.03;


     }


    if (fragCoord.y==0) fragColor = vec4(pos);
    if (fragCoord.y==1) fragColor = quat;
    if (fragCoord.y==2) fragColor = vec4(vel, 0.0);
    if (fragCoord.y==3) fragColor = vec4(rotvel, 0.0);
    if (fragCoord.y==4) fragColor = vec4(shape);
    if (fragCoord.y==5) fragColor = vec4(mass);
    if (fragCoord.y==6) fragColor = vec4(pressure);
}
